import React, { useEffect, useState } from "react";
import {
  Box,
  TextField,
  List,
  ListItem,
  ListItemText,
  Paper,
  InputAdornment,
  Typography,
  CircularProgress,
  IconButton,
} from "@mui/material";
import SearchIcon from "@mui/icons-material/Search";
import ClearIcon from "@mui/icons-material/Clear";
import axios from "../axiosInstance";
import { useNavigate } from "react-router-dom";

const staticSuggestions = [
  "School",
  "Hospital",
  "AC Repair",
  "Restaurant",
  "Coaching",
];
const staticCategories = [
  "Education",
  "Healthcare",
  "Electronics",
  "Food",
  "Services",
];

const SearchBar = () => {
  const [query, setQuery] = useState("");
  const [showDropdown, setShowDropdown] = useState(false);
  const [typingIndex, setTypingIndex] = useState(0);
  const [displayText, setDisplayText] = useState("");
  const [charIndex, setCharIndex] = useState(0);
  const [loading, setLoading] = useState(false);
  const [results, setResults] = useState({
    businesses: [],
    products: [],
    categories: [],
  });
  const [recentSearches, setRecentSearches] = useState(() => {
    const saved = localStorage.getItem("recentSearches");
    return saved ? JSON.parse(saved) : [];
  });

  const navigate = useNavigate();

  // Typing animation effect
  useEffect(() => {
    const interval = setInterval(() => {
      const currentWord = staticSuggestions[typingIndex];
      setDisplayText(currentWord.slice(0, charIndex + 1));
      setCharIndex((prev) => prev + 1);

      if (charIndex >= currentWord.length) {
        setTimeout(() => {
          setCharIndex(0);
          setTypingIndex((prev) => (prev + 1) % staticSuggestions.length);
        }, 1000);
      }
    }, 150);

    return () => clearInterval(interval);
  }, [charIndex, typingIndex]);

  // API call when query changes
  useEffect(() => {
    if (!query.trim()) {
      setResults({ businesses: [], products: [], categories: [] });
      return;
    }

    const delayDebounce = setTimeout(async () => {
      setLoading(true);
      try {
        const res = await axios.get(`/api/search?q=${query}`);
        setResults({
          businesses: res.data.data.businesses,
          products: res.data.data.products,
          categories: res.data.data.categories || [],
        });
      } catch (err) {
        console.error("Search error:", err);
      } finally {
        setLoading(false);
      }
    }, 500);

    return () => clearTimeout(delayDebounce);
  }, [query]);

  // Save recent search
  const saveRecentSearch = (text) => {
    const updated = [
      text,
      ...recentSearches.filter((item) => item !== text),
    ].slice(0, 5);
    setRecentSearches(updated);
    localStorage.setItem("recentSearches", JSON.stringify(updated));
  };

  // Navigate based on match
  const handleSelect = (text) => {
    setQuery(text);
    setShowDropdown(false);
    saveRecentSearch(text);

    const lowerText = text.toLowerCase();

    const matchedCategory = results.categories.find((cat) =>
      cat.name?.toLowerCase().includes(lowerText)
    );
    if (matchedCategory) {
      return navigate(`/category/${matchedCategory._id}`);
    }

    const matchedBusiness = results.businesses.find(
      (b) => b.businessName?.toLowerCase() === lowerText
    );
    if (matchedBusiness) {
      return navigate(
        `/category/${matchedBusiness.businessName}/${matchedBusiness._id}`
      );
    }

    const matchedProduct = results.products.find(
      (p) => p.name?.toLowerCase() === lowerText
    );
    if (matchedProduct) {
      return navigate(`/product/${matchedProduct._id}`);
    }
  };

  const handleClearRecent = (text) => {
    const updated = recentSearches.filter((item) => item !== text);
    setRecentSearches(updated);
    localStorage.setItem("recentSearches", JSON.stringify(updated));
  };

  return (
    <Box
      sx={{
        width: "100%",
        maxWidth: 600,
        margin: "auto",
        mt: 2,
        mb:2,
        position: "relative",
      }}
    >
      <TextField
        fullWidth
        value={query}
        onChange={(e) => setQuery(e.target.value.trimStart())}
        onClick={() => setShowDropdown(true)}
        onBlur={() => setTimeout(() => setShowDropdown(false), 200)}
        placeholder={`Search ${displayText}...`}
        InputProps={{
          startAdornment: (
            <InputAdornment position="start">
              <SearchIcon color="primary" />
            </InputAdornment>
          ),
        }}
        sx={{ backgroundColor: "white", borderRadius: 2 }}
      />

      {showDropdown && (
        <Paper
          elevation={3}
          sx={{
            position: "absolute",
            top: "100%",
            left: 0,
            right: 0,
            zIndex: 10,
            borderRadius: 2,
            mt: 1,
            maxHeight: 400,
            overflowY: "auto",
          }}
        >
          {/* Recent Searches */}
          {recentSearches.length > 0 && (
            <Box px={2} pt={1}>
              <Box
                display="flex"
                alignItems="center"
                justifyContent="space-between"
                mb={1}
              >
                <Typography variant="subtitle2" fontWeight="bold">
                  Recent Searches
                </Typography>
                <IconButton
                  size="small"
                  onClick={() => {
                    setRecentSearches([]);
                    localStorage.removeItem("recentSearches");
                  }}
                >
                  <ClearIcon fontSize="small" color="error" />
                </IconButton>
              </Box>
              <List dense>
                {recentSearches.map((item, index) => (
                  <ListItem
                    key={index}
                    button
                    onClick={() => handleSelect(item)}
                  >
                    <ListItemText primary={item} />
                  </ListItem>
                ))}
              </List>
            </Box>
          )}

          {/*  Popular Categories */}
          <Box px={2} pt={1}>
            <Typography variant="subtitle2" fontWeight="bold" mb={1}>
              Popular Categories
            </Typography>
            <List dense>
              {staticCategories.map((item, index) => (
                <ListItem key={index} button onClick={() => handleSelect(item)}>
                  <ListItemText primary={item} />
                </ListItem>
              ))}
            </List>
          </Box>

          {/*  Loader */}
          {loading && (
            <Box textAlign="center" py={2}>
              <CircularProgress size={24} />
            </Box>
          )}
          {/*  Categories */}
          {!loading && results.categories.length > 0 && (
            <Box px={2}>
              <Typography variant="subtitle2" fontWeight="bold" mt={1}>
                Categories
              </Typography>
              <List dense>
                {results.categories.map((cat) => (
                  <ListItem
                    key={cat._id}
                    button
                    onClick={() => handleSelect(cat.name)}
                  >
                    <ListItemText primary={cat.name} />
                  </ListItem>
                ))}
              </List>
            </Box>
          )}

          {/*  Businesses */}
          {!loading && results.businesses.length > 0 && (
            <Box px={2}>
              <Typography variant="subtitle2" fontWeight="bold" mt={1}>
                Businesses
              </Typography>
              <List dense>
                {results.businesses.map((b) => (
                  <ListItem
                    key={b._id}
                    button
                    onClick={() => handleSelect(b.businessName)}
                  >
                    <ListItemText
                      primary={`${b.businessName} – ${b.city}, ${b.state}`}
                    />
                  </ListItem>
                ))}
              </List>
            </Box>
          )}

          {/*  Products */}
          {!loading && results.products.length > 0 && (
            <Box px={2}>
              <Typography variant="subtitle2" fontWeight="bold" mt={1}>
                Products
              </Typography>
              <List dense>
                {results.products.map((p) => (
                  <ListItem
                    key={p._id}
                    button
                    onClick={() => handleSelect(p.name)}
                  >
                    <ListItemText
                      primary={`${p.name} – ${
                        p.businessId?.businessName || ""
                      }`}
                    />
                  </ListItem>
                ))}
              </List>
            </Box>
          )}
        </Paper>
      )}
    </Box>
  );
};

export default SearchBar;
